1	<script lang="ts">
2		/**
3		 * Spending Report page
4		 *
5		 * Rolls a year's Expenses up through Category → Grouping → Area of Importance
6		 * and renders the month-by-month grid (subtotals per Grouping and Importance,
7		 * a Year-to-Date column, Uncategorized at the bottom, Grand Total).
8		 *
9		 * All aggregation is the pure `buildSpendingReport` — this page only loads the
10		 * data and paints the grid. Design: docs/plans/2026-07-09-spending-report-design.md
11		 */
12	
13		import { onMount } from 'svelte';
14		import { resolve } from '$app/paths';
15		import { goto } from '$app/navigation';
16		import { supabase } from '$lib/supabaseClient';
17		import { ExpenseService } from '$lib/services/ExpenseService';
18		import { CategoryService } from '$lib/services/CategoryService';
19		import { getDefaultFamilyId } from '$lib/utils/familyUtils';
20		import { formatCurrency } from '$lib/utils/formatCurrency';
21		import {
22			buildSpendingReport,
23			type SpendingReport,
24			type SpendingCategory,
25			type Cell,
26			type ReportRow
27		} from '$lib/utils/spendingReport';
28		import {
29			withPriorPeriod,
30			hasPriorData,
31			spendingChange,
32			type SpendingChange
33		} from '$lib/utils/spendingComparison';
34		import {
35			buildSpendingDrilldownParams,
36			type DrilldownScope,
37			type DrilldownColumn
38		} from '$lib/utils/spendingDrilldown';
39		import type { CategoryGroup } from '$lib/types/Hierarchy';
40		import SpendingChart from '$lib/components/SpendingChart.svelte';
41		import type { Session } from '@supabase/supabase-js';
42		import type { PageData } from './$types';
43	
44		let { data }: { data: PageData } = $props();
45	
46		let session: Session | null = $state(null);
47		let familyId: string | null = $state(null);
48		// The selected year comes from the `+page.ts` load (URL `?year=`). Load
49		// re-runs with the right URL on every navigation — arrows, Back, refresh — so
50		// this stays correct where the earlier client-side derivations went stale.
51		let year = $derived(data.year);
52		let view = $state<'table' | 'chart'>('table');
53		let loading = $state(true);
54		let error: string | null = $state(null);
55		let report = $state<SpendingReport | null>(null);
56		// Year-over-year comparison. `compare` is the user's toggle; `hasPrior` says the
57		// prior year actually has data. The effective `comparing` gates both views, so
58		// the toggle can stay pressed while inert on a year whose predecessor is empty.
59		let compare = $state(false);
60		let hasPrior = $state(false);
61		const priorYear = $derived(year - 1);
62		const comparing = $derived(compare && hasPrior);
63		// Kept in state (not just local to loadReport) so cell drill-down can expand a
64		// Grouping/Importance to its member category ids.
65		let categories = $state<SpendingCategory[]>([]);
66		let groups = $state<CategoryGroup[]>([]);
67	
68		onMount(async () => {
69			const { data } = await supabase.auth.getSession();
70			session = data.session;
71			if (!session) {
72				loading = false;
73				return;
74			}
75	
76			familyId = await getDefaultFamilyId();
77			if (!familyId) {
78				error = 'No family found. Please contact support.';
79				loading = false;
80			}
81		});
82	
83		// Load (or reload) whenever the resolved family or the URL year changes. The
84		// URL is the source of truth for `year`, so a refresh / back-navigation to a
85		// past year reloads that year rather than the current one.
86		$effect(() => {
87			const reportYear = year; // track the derived year
88			if (session?.user && familyId) {
89				loadReport(reportYear);
90			}
91		});
92	
93		async function loadReport(reportYear: number) {
94			if (!session?.user || !familyId) return;
95	
96			try {
97				loading = true;
98				error = null;
99	
100				const categoryService = new CategoryService(supabase);
101				const expenseService = new ExpenseService(supabase);
102	
103				// Seed the default hierarchy the first time a family opens the report
104				// (idempotent server-side), mirroring how categories self-initialize.
105				let importanceAreas = await categoryService.getFamilyImportanceAreas(familyId);
106				if (importanceAreas.length === 0) {
107					await categoryService.createDefaultHierarchy(familyId);
108					importanceAreas = await categoryService.getFamilyImportanceAreas(familyId);
109				}
110	
111				// The prior year is fetched alongside so the comparison toggle repaints
112				// instantly (no refetch) and we know up-front whether to enable it. A
113				// family's yearly receipt count is small, so the extra query is negligible.
114				const [loadedGroups, loadedCategories, expenses, priorExpenses] = await Promise.all([
115					categoryService.getFamilyGroups(familyId),
116					categoryService.getFamilyCategories(familyId),
117					expenseService.getExpenses(session.user.id, {
118						startDate: `${reportYear}-01-01`,
119						endDate: `${reportYear}-12-31`
120					}),
121					expenseService.getExpenses(session.user.id, {
122						startDate: `${reportYear - 1}-01-01`,
123						endDate: `${reportYear - 1}-12-31`
124					})
125				]);
126	
127				groups = loadedGroups;
128				categories = loadedCategories;
129				const current = buildSpendingReport(
130					expenses,
131					loadedCategories,
132					loadedGroups,
133					importanceAreas,
134					reportYear
135				);
136				const prior = buildSpendingReport(
137					priorExpenses,
138					loadedCategories,
139					loadedGroups,
140					importanceAreas,
141					reportYear - 1
142				);
143				hasPrior = hasPriorData(prior);
144				// Attaches same-period prior-year totals to `current`'s rows (Jan → the
145				// year's last visible month). Harmless when there's no prior data.
146				report = withPriorPeriod(current, prior);
147			} catch (err) {
148				console.error('Error loading spending report:', err);
149				error = err instanceof Error ? err.message : 'Failed to load the spending report';
150			} finally {
151				loading = false;
152			}
153		}
154	
155		function changeYear(delta: number) {
156			// Navigate to the new year in the URL; `load` re-runs, `data.year` updates,
157			// and the reload effect follows. replaceState keeps the back-stack clean so
158			// Back returns to wherever the user came from, not each year they stepped
159			// through. keepFocus/noScroll avoid the arrow losing focus / a scroll jump.
160			goto(resolve(`/spending?year=${year + delta}`), {
161				replaceState: true,
162				keepFocus: true,
163				noScroll: true
164			});
165		}
166	
167		/** A cell renders blank when no receipts fell in it, otherwise the amount. */
168		function cellText(cell: Cell): string {
169			return cell.count === 0 ? '' : formatCurrency(cell.amount);
170		}
171	
172		/**
173		 * The drill-down scope for a detail row: a real category when the row maps to
174		 * one (including a named-but-ungrouped Uncategorized row), otherwise the
175		 * "(No category)" catch-all drills to the uncategorized Expenses filter.
176		 */
177		function rowScope(row: ReportRow): DrilldownScope {
178			return row.categoryId
179				? { kind: 'category', categoryId: row.categoryId }
180				: { kind: 'uncategorized' };
181		}
182	
183		/**
184		 * The Expenses-view query a clicked cell links to, filtered to exactly what it
185		 * sums. Returns just the query string; the template builds the `/expenses?…`
186		 * template literal and wraps it in `resolve()` (both SvelteKit's typed `resolve`
187		 * and the no-navigation-without-resolve lint rule want that at the call site).
188		 */
189		function drilldownQuery(scope: DrilldownScope, column: DrilldownColumn): string {
190			return buildSpendingDrilldownParams(scope, column, year, categories, groups).toString();
191		}
192	
193		const hasData = $derived(report !== null && report.months.length > 0);
194	</script>
195	
196	<svelte:head>
197		<title>Spending — YFL Expense Tracker</title>
198	</svelte:head>
199	
200	<div class="spending-page">
201		<div class="mb-6 flex flex-wrap items-center justify-between gap-3">
202			<div>
203				<h1 class="mb-2 text-2xl font-bold">Spending</h1>
204				<p class="text-gray-600">
205					Your expenses by Area of Importance, Grouping, and Category. Amounts in CAD.
206				</p>
207			</div>
208			<div class="flex items-center gap-4">
209				<a
210					href={resolve('/spending/hierarchy')}
211					class="rounded-sm border border-gray-300 px-3 py-1 text-sm hover:bg-gray-100"
212				>
213					Edit hierarchy
214				</a>
215				<div class="inline-flex overflow-hidden rounded-sm border border-gray-300" role="group">
216					<button
217						type="button"
218						class="px-3 py-1 text-sm {view === 'table'
219							? 'bg-indigo-600 text-white'
220							: 'bg-white text-gray-700 hover:bg-gray-100'}"
221						aria-pressed={view === 'table'}
222						onclick={() => (view = 'table')}
223					>
224						Table
225					</button>
226					<button
227						type="button"
228						class="border-l border-gray-300 px-3 py-1 text-sm {view === 'chart'
229							? 'bg-indigo-600 text-white'
230							: 'bg-white text-gray-700 hover:bg-gray-100'}"
231						aria-pressed={view === 'chart'}
232						onclick={() => (view = 'chart')}
233					>
234						Chart
235					</button>
236				</div>
237				<button
238					type="button"
239					class="rounded-sm border px-3 py-1 text-sm disabled:cursor-not-allowed disabled:opacity-50 {comparing
240						? 'border-indigo-600 bg-indigo-600 text-white'
241						: 'border-gray-300 bg-white text-gray-700 hover:bg-gray-100'}"
242					aria-pressed={comparing}
243					disabled={!hasPrior}
244					title={hasPrior
245						? `Compare each total with the same period of ${priorYear}`
246						: `No ${priorYear} data to compare`}
247					onclick={() => (compare = !compare)}
248				>
249					Compare {priorYear}
250				</button>
251				<div class="flex items-center gap-2">
252					<button
253						type="button"
254						class="rounded-sm border border-gray-300 px-3 py-1 text-sm hover:bg-gray-100"
255						onclick={() => changeYear(-1)}
256						aria-label="Previous year"
257					>
258						←
259					</button>
260					<span class="min-w-16 text-center text-lg font-semibold" aria-live="polite">{year}</span>
261					<button
262						type="button"
263						class="rounded-sm border border-gray-300 px-3 py-1 text-sm hover:bg-gray-100"
264						onclick={() => changeYear(1)}
265						aria-label="Next year"
266					>
267						→
268					</button>
269				</div>
270			</div>
271		</div>
272	
273		{#if loading}
274			<div class="flex items-center justify-center p-8 text-gray-500">Loading spending report…</div>
275		{:else if error}
276			<div class="rounded-sm border border-red-200 bg-red-50 p-4 text-red-700">{error}</div>
277		{:else if !hasData}
278			<div class="rounded-sm border border-gray-200 bg-gray-50 p-8 text-center text-gray-500">
279				No expenses recorded for {year}.
280			</div>
281		{:else if report}
282			{#if report.missingAmountCount > 0}
283				<p class="mb-3 text-sm text-yellow-700">
284					⚠ {report.missingAmountCount} receipt{report.missingAmountCount === 1 ? '' : 's'} in {year}
285					{report.missingAmountCount === 1 ? 'has' : 'have'} no amount and count as $0. Open them on the
286					Receipts page to fix.
287				</p>
288			{/if}
289	
290			{#if comparing}
291				<p class="mb-3 text-sm text-gray-500">
292					Comparing <span class="font-medium">Jan–{report.monthLabels.at(-1)} {year}</span> with the
293					same period of {priorYear} (whole months).
294				</p>
295			{/if}
296	
297			{#snippet nameCell(name: string, scope: DrilldownScope)}
298				<!--
299					A row's label links to every Expense the row rolls up for the year (its
300					Year-to-Date column), so the whole row — not just each month cell — is
301					clickable. Long names truncate to one line; the full name shows on hover.
302				-->
303				<a
304					class="block max-w-64 truncate hover:text-indigo-600 hover:underline"
305					href={resolve(`/expenses?${drilldownQuery(scope, { kind: 'ytd' })}`)}
306					title={name}>{name}</a
307				>
308			{/snippet}
309	
310			{#snippet valueCells(row: ReportRow, scope: DrilldownScope)}
311				{#each row.cells as cell, i (cell)}
312					<td class="px-3 py-1 text-right tabular-nums">
313						{#if cell.count > 0}
314							<!-- months run Jan → maxMonth contiguously, so column i is month i+1 -->
315							<a
316								class="hover:text-indigo-600 hover:underline"
317								href={resolve(`/expenses?${drilldownQuery(scope, { kind: 'month', month: i + 1 })}`)}
318								title="View these expenses">{cellText(cell)}</a
319							>
320						{/if}
321					</td>
322				{/each}
323				<td class="px-3 py-1 text-right font-semibold tabular-nums">
324					{#if row.ytd.count > 0}
325						<a
326							class="hover:text-indigo-600 hover:underline"
327							href={resolve(`/expenses?${drilldownQuery(scope, { kind: 'ytd' })}`)}
328							title="View these expenses">{cellText(row.ytd)}</a
329						>
330					{/if}
331				</td>
332				{#if comparing}
333					<!-- Change vs the same Jan→last-month period of the prior year. -->
334					{@const change = spendingChange(row.ytd.amount, row.priorYtd ?? 0)}
335					<td
336						class="px-3 py-1 text-right tabular-nums {change.direction === 'up'
337							? 'text-red-600'
338							: change.direction === 'down'
339								? 'text-green-600'
340								: 'text-gray-400'}"
341					>
342						{@render changeText(change)}
343					</td>
344				{/if}
345			{/snippet}
346	
347			{#snippet changeText(change: SpendingChange)}
348				{#if change.direction === 'flat'}
349					—
350				{:else}
351					{change.delta > 0 ? '+' : ''}{formatCurrency(change.delta)}
352					{#if change.pct !== null}
353						({change.pct > 0 ? '+' : ''}{change.pct.toFixed(0)}%)
354					{:else}
355						(new)
356					{/if}
357				{/if}
358			{/snippet}
359	
360			{#if view === 'table'}
361				<div class="overflow-x-auto">
362					<table class="min-w-full border-collapse text-sm">
363						<thead>
364							<tr class="border-b-2 border-gray-300 bg-gray-50 text-gray-700">
365								<th class="px-3 py-2 text-left font-semibold">Category</th>
366								{#each report.monthLabels as label, i (label)}
367									<!-- A column header links to every Expense in that month, across all categories. -->
368									<th class="px-3 py-2 text-right font-semibold">
369										<a
370											class="hover:text-indigo-600 hover:underline"
371											href={resolve(
372												`/expenses?${drilldownQuery({ kind: 'grandTotal' }, { kind: 'month', month: i + 1 })}`
373											)}
374											title="View all expenses for {label}">{label}</a
375										>
376									</th>
377								{/each}
378								<th class="px-3 py-2 text-right font-semibold">
379									<a
380										class="hover:text-indigo-600 hover:underline"
381										href={resolve(
382											`/expenses?${drilldownQuery({ kind: 'grandTotal' }, { kind: 'ytd' })}`
383										)}
384										title="View all expenses for {year}">Year to Date</a
385									>
386								</th>
387								{#if comparing}
388									<th
389										class="px-3 py-2 text-right font-semibold"
390										title="Change vs the same period of {priorYear}">vs {priorYear}</th
391									>
392								{/if}
393							</tr>
394						</thead>
395						<tbody>
396							{#each report.importances as importance (importance.name)}
397								<tr class="bg-indigo-100 font-semibold text-indigo-900">
398									<td class="px-3 py-1" colspan={report.months.length + (comparing ? 3 : 2)}>
399										<a
400											class="hover:underline"
401											href={resolve(
402												`/expenses?${drilldownQuery({ kind: 'importance', importanceId: importance.id }, { kind: 'ytd' })}`
403											)}
404											title="View all {importance.name} expenses for {year}">{importance.name}</a
405										>
406									</td>
407								</tr>
408								{#each importance.groups as group (group.name)}
409									{#each group.rows as row (row.name)}
410										<tr class="border-b border-gray-100">
411											<td class="px-3 py-1 pl-8">{@render nameCell(row.name, rowScope(row))}</td>
412											{@render valueCells(row, rowScope(row))}
413										</tr>
414									{/each}
415									<tr class="border-b border-gray-200 bg-gray-100 font-medium">
416										<td class="px-3 py-1 pl-6"
417											>{@render nameCell(`${group.name} Total`, {
418												kind: 'group',
419												groupId: group.id ?? ''
420											})}</td
421										>
422										{@render valueCells(group.subtotal, {
423											kind: 'group',
424											groupId: group.id ?? ''
425										})}
426									</tr>
427								{/each}
428								<tr class="border-b-2 border-indigo-200 bg-indigo-50 font-semibold">
429									<td class="px-3 py-1"
430										>{@render nameCell(`${importance.name} Total`, {
431											kind: 'importance',
432											importanceId: importance.id
433										})}</td
434									>
435									{@render valueCells(importance.subtotal, {
436										kind: 'importance',
437										importanceId: importance.id
438									})}
439								</tr>
440							{/each}
441	
442							{#if report.uncategorized}
443								<tr class="bg-amber-100 font-semibold text-amber-900">
444									<td class="px-3 py-1" colspan={report.months.length + (comparing ? 3 : 2)}>
445										<a
446											class="hover:underline"
447											href={resolve(
448												`/expenses?${drilldownQuery({ kind: 'uncategorized' }, { kind: 'ytd' })}`
449											)}
450											title="View all Uncategorized expenses for {year}">Uncategorized</a
451										>
452									</td>
453								</tr>
454								{#each report.uncategorized.rows as row (row.name)}
455									<tr class="border-b border-gray-100">
456										<td class="px-3 py-1 pl-8">{@render nameCell(row.name, rowScope(row))}</td>
457										{@render valueCells(row, rowScope(row))}
458									</tr>
459								{/each}
460								<tr class="border-b-2 border-amber-200 bg-amber-50 font-semibold">
461									<td class="px-3 py-1"
462										>{@render nameCell('Uncategorized Total', { kind: 'uncategorized' })}</td
463									>
464									{@render valueCells(report.uncategorized.subtotal, { kind: 'uncategorized' })}
465								</tr>
466							{/if}
467	
468							<tr class="border-t-2 border-gray-400 bg-gray-200 font-bold">
469								<td class="px-3 py-2">{@render nameCell('Grand Total', { kind: 'grandTotal' })}</td>
470								{@render valueCells(report.grandTotal, { kind: 'grandTotal' })}
471							</tr>
472						</tbody>
473					</table>
474				</div>
475			{:else}
476				<SpendingChart {report} compare={comparing} />
477			{/if}
478		{/if}
479	</div>
