1	/**
2	 * Spending Report aggregation (pure)
3	 *
4	 * Rolls a year's Expenses up through the hierarchy
5	 *   Category → Grouping → Area of Importance
6	 * into the month-by-month grid the report renders. No I/O, no dates-from-clock,
7	 * no Supabase — a plain function so it can be unit-tested like the CSV parsers.
8	 *
9	 * Design: docs/plans/2026-07-09-spending-report-design.md
10	 *
11	 * Conventions baked in here (all settled during the grill):
12	 * - Source is Expenses (receipts), bucketed by `transaction_date` (purchase date).
13	 * - Amounts are normalized to the family's currency via the stored FX rate:
14	 *   amount * (exchange_rate_to_cad ?? 1). Refunds are negative and are KEPT
15	 *   negative so they net out (unlike the CSV/PDF exporters, which abs them).
16	 * - Visible month columns run January → the last month that has any expense.
17	 * - A cell with no receipts renders blank; a cell with receipts summing to 0
18	 *   renders 0.00. So each cell carries both an amount and a receipt count.
19	 * - Rows are only emitted where there was activity (zero-activity suppression is
20	 *   automatic — we build rows from the data, not from the full hierarchy).
21	 * - Categories with no Grouping (group_id null / unknown) and receipts with no
22	 *   category land in a bottom "Uncategorized" section, which IS included in the
23	 *   grand total.
24	 */
25	
26	import type { ImportanceArea, CategoryGroup } from '$lib/types/Hierarchy';
27	
28	// Re-export the hierarchy types so callers can import them from here too.
29	export type { ImportanceArea, CategoryGroup } from '$lib/types/Hierarchy';
30	
31	/** The fields of an Expense this aggregation needs. `Expense` satisfies it structurally. */
32	export interface SpendingExpense {
33		total_amount: number | null;
34		transaction_date: string; // 'YYYY-MM-DD'
35		category_id: string | null;
36		exchange_rate_to_cad: number | null;
37	}
38	
39	/** Minimal category shape needed to resolve a receipt to its Grouping. */
40	export interface SpendingCategory {
41		id: string;
42		name: string;
43		group_id?: string | null;
44	}
45	
46	/** One month/YTD cell: the summed amount plus how many receipts contributed. */
47	export interface Cell {
48		amount: number;
49		count: number;
50	}
51	
52	/** A single printed line: a category, a subtotal, or the grand total. */
53	export interface ReportRow {
54		name: string;
55		/**
56		 * The category this row maps to 1:1, for drill-down into the Expenses view.
57		 * Set on category detail rows (including a named-but-ungrouped Uncategorized
58		 * row); undefined on the "(No category)" row and on all subtotal/grand-total
59		 * rows. See `spendingDrilldown.ts`.
60		 */
61		categoryId?: string;
62		/** One cell per visible month (parallel to `SpendingReport.months`). */
63		cells: Cell[];
64		/** Year-to-date roll-up across the visible months. */
65		ytd: Cell;
66		/**
67		 * Same-period prior-year total (January → the current report's last visible
68		 * month, whole months only), attached by `withPriorPeriod` for the
69		 * year-over-year comparison. Undefined when no comparison is active. See
70		 * `spendingComparison.ts`.
71		 */
72		priorYtd?: number;
73	}
74	
75	/** A Grouping and its category rows, with the group subtotal. */
76	export interface GroupSection {
77		name: string;
78		/** The Grouping's id, for drill-down; undefined for the synthetic Uncategorized section. */
79		id?: string;
80		rows: ReportRow[];
