94	export interface SpendingReport {
95		year: number;
96		/** 1-based month numbers shown as columns, e.g. [1,2,3,4,5,6]. Empty if no data. */
97		months: number[];
98		/** Short labels parallel to `months`, e.g. ['Jan','Feb',...]. */
99		monthLabels: string[];
100		importances: ImportanceSection[];
101		/** Uncategorized spend as its own section; null when everything is categorized. */
102		uncategorized: GroupSection | null;
103		/** Bottom-right roll-up across everything, including Uncategorized. */
104		grandTotal: ReportRow;
105		/** Receipts in `year` with a null amount (counted as $0). Surfaced as a footnote. */
106		missingAmountCount: number;
107	}
108	
109	const MONTH_LABELS = [
110		'Jan',
111		'Feb',
112		'Mar',
113		'Apr',
114		'May',
115		'Jun',
116		'Jul',
117		'Aug',
118		'Sep',
119		'Oct',
120		'Nov',
121		'Dec'
122	];
123	
124	const UNCATEGORIZED_SECTION = 'Uncategorized';
125	const NO_CATEGORY_ROW = '(No category)';
126	
127	/**
128	 * Parse the year and 1-based month out of a 'YYYY-MM-DD' string without
129	 * constructing a Date — bare date strings parse as UTC midnight and can shift a
130	 * day (and thus a month) west of UTC. Returns null for anything unparseable.
131	 */
132	function yearMonth(dateStr: string): { year: number; month: number } | null {
133		if (!dateStr || dateStr.length < 7) return null;
134		const year = Number(dateStr.slice(0, 4));
135		const month = Number(dateStr.slice(5, 7));
136		if (!Number.isInteger(year) || !Number.isInteger(month) || month < 1 || month > 12) {
137			return null;
138		}
139		return { year, month };
140	}
141	
142	/** CAD (family-currency) value of an expense; refunds stay negative. */
143	function normalizedAmount(e: SpendingExpense): number {
144		if (e.total_amount == null) return 0;
145		return e.total_amount * (e.exchange_rate_to_cad ?? 1);
146	}
147	
148	function emptyCells(monthCount: number): Cell[] {
149		return Array.from({ length: monthCount }, () => ({ amount: 0, count: 0 }));
150	}
151	
152	function addInto(target: Cell, amount: number): void {
153		target.amount += amount;
154		target.count += 1;
155	}
156	
157	/** Accumulate one row's cells (and ytd) into another (for subtotals/grand total). */
158	function accumulate(target: ReportRow, source: ReportRow): void {
159		for (let i = 0; i < source.cells.length; i++) {
160			target.cells[i].amount += source.cells[i].amount;
161			target.cells[i].count += source.cells[i].count;
162		}
163		target.ytd.amount += source.ytd.amount;
164		target.ytd.count += source.ytd.count;
165	}
166	
167	function makeRow(name: string, monthCount: number, categoryId?: string): ReportRow {
168		return { name, categoryId, cells: emptyCells(monthCount), ytd: { amount: 0, count: 0 } };
169	}
170	
171	/**
172	 * Internal accumulator keyed by group then category, so we can build the tree in
173	 * one pass over the expenses and sort/emit it at the end.
174	 */
175	interface GroupAccumulator {
176		name: string;
177		/** The Grouping's id; undefined for the synthetic Uncategorized bucket. */
178		id?: string;
179		rows: Map<string, ReportRow>; // category name → row
180	}
181	
182	/**
183	 * Build the spending report grid for a single calendar year.
184	 *
185	 * @param expenses      All expenses (the caller may pass more than `year`; we filter).
186	 * @param categories    Family categories, each carrying its `group_id`.
187	 * @param groups        Family groupings, each carrying its `importance_area_id`.
188	 * @param importanceAreas Family importance areas with `sort_order`.
189	 * @param year          The calendar year to report on.
190	 */
191	export function buildSpendingReport(
192		expenses: SpendingExpense[],
193		categories: SpendingCategory[],
194		groups: CategoryGroup[],
195		importanceAreas: ImportanceArea[],
196		year: number
197	): SpendingReport {
198		// --- lookups -------------------------------------------------------------
199		const categoryById = new Map(categories.map((c) => [c.id, c]));
200		const groupById = new Map(groups.map((g) => [g.id, g]));
201		const importanceById = new Map(importanceAreas.map((a) => [a.id, a]));
202	
203		// --- pass 1: which months are in play, and the missing-amount count --------
204		let maxMonth = 0;
205		let missingAmountCount = 0;
206		const inYear: { e: SpendingExpense; month: number }[] = [];
207		for (const e of expenses) {
208			const ym = yearMonth(e.transaction_date);
209			if (!ym || ym.year !== year) continue;
210			inYear.push({ e, month: ym.month });
211			if (ym.month > maxMonth) maxMonth = ym.month;
212			if (e.total_amount == null) missingAmountCount += 1;
213		}
214	
215		if (maxMonth === 0) {
216			// No expenses this year — empty report (component shows an empty state).
217			return {
218				year,
219				months: [],
220				monthLabels: [],
221				importances: [],
222				uncategorized: null,
223				grandTotal: makeRow('Grand Total', 0),
224				missingAmountCount: 0
225			};
226		}
227	
228		const months = Array.from({ length: maxMonth }, (_, i) => i + 1);
229		const monthLabels = months.map((m) => MONTH_LABELS[m - 1]);
230		const monthCount = months.length;
231		const monthIndex = (m: number) => m - 1; // month 1 → column 0
232	
233		// --- pass 2: bucket each expense into importance → group → category --------
234		// Keyed by importance area id; a synthetic key holds the Uncategorized bucket.
235		const importanceAcc = new Map<string, Map<string, GroupAccumulator>>();
236		const uncategorizedAcc: GroupAccumulator = { name: UNCATEGORIZED_SECTION, rows: new Map() };
237	
238		const ensureRow = (acc: GroupAccumulator, name: string, categoryId?: string): ReportRow => {
239			let row = acc.rows.get(name);
240			if (!row) {
241				row = makeRow(name, monthCount, categoryId);
242				acc.rows.set(name, row);
243			}
244			return row;
245		};
246	
247		for (const { e, month } of inYear) {
248			const amount = normalizedAmount(e);
249			const category = e.category_id != null ? categoryById.get(e.category_id) : undefined;
250			const group = category?.group_id != null ? groupById.get(category.group_id) : undefined;
251			const importance = group ? importanceById.get(group.importance_area_id) : undefined;
252	
253			let targetGroupAcc: GroupAccumulator;
254			let rowName: string;
255	
256			if (category && group && importance) {
257				let groupsForImportance = importanceAcc.get(importance.id);
258				if (!groupsForImportance) {
259					groupsForImportance = new Map();
260					importanceAcc.set(importance.id, groupsForImportance);
261				}
262				let groupAcc = groupsForImportance.get(group.id);
263				if (!groupAcc) {
264					groupAcc = { name: group.name, id: group.id, rows: new Map() };
265					groupsForImportance.set(group.id, groupAcc);
266				}
267				targetGroupAcc = groupAcc;
268				rowName = category.name;
269			} else {
270				// Uncategorized: no category, unknown category, category without a group,
271				// or a group/importance that no longer resolves.
272				targetGroupAcc = uncategorizedAcc;
273				rowName = category ? category.name : NO_CATEGORY_ROW;
274			}
275	
276			// A named row (even in Uncategorized) carries its real category id; the
277			// "(No category)" catch-all stays id-less.
278			const row = ensureRow(targetGroupAcc, rowName, category?.id);
279			addInto(row.cells[monthIndex(month)], amount);
280			addInto(row.ytd, amount);
281		}
282	
283		// --- emit: sort and roll up subtotals -------------------------------------
284		const buildGroupSection = (acc: GroupAccumulator, subtotalName: string): GroupSection => {
285			const rows = [...acc.rows.values()].sort((a, b) => byName(a.name, b.name));
286			const subtotal = makeRow(subtotalName, monthCount);
287			for (const row of rows) accumulate(subtotal, row);
288			return { name: acc.name, id: acc.id, rows, subtotal };
289		};
290	
291		const sortedImportances = [...importanceAreas]
292			.filter((a) => importanceAcc.has(a.id))
293			.sort((a, b) => a.sort_order - b.sort_order || byName(a.name, b.name));
294	
295		const importances: ImportanceSection[] = sortedImportances.map((area) => {
296			const groupAccs = importanceAcc.get(area.id)!;
297			const groupSections = [...groupAccs.values()]
298				.map((g) => buildGroupSection(g, `${g.name} Total`))
299				.sort((a, b) => byName(a.name, b.name));
300			const subtotal = makeRow(`${area.name} Total`, monthCount);
301			for (const gs of groupSections) accumulate(subtotal, gs.subtotal);
302			return {
303				name: area.name,
304				id: area.id,
305				sortOrder: area.sort_order,
306				groups: groupSections,
307				subtotal
308			};
309		});
310	
311		const uncategorized =
312			uncategorizedAcc.rows.size > 0
313				? buildGroupSection(uncategorizedAcc, `${UNCATEGORIZED_SECTION} Total`)
314				: null;
315	
316		// --- grand total (includes Uncategorized) ---------------------------------
317		const grandTotal = makeRow('Grand Total', monthCount);
318		for (const imp of importances) accumulate(grandTotal, imp.subtotal);
319		if (uncategorized) accumulate(grandTotal, uncategorized.subtotal);
320	
321		return {
322			year,
323			months,
324			monthLabels,
325			importances,
326			uncategorized,
327			grandTotal,
328			missingAmountCount
329		};
330	}
331	
332	/** Case-insensitive name sort, "(No category)" sinks to the bottom. */
333	function byName(a: string, b: string): number {
334		if (a === NO_CATEGORY_ROW) return 1;
335		if (b === NO_CATEGORY_ROW) return -1;
336		return a.localeCompare(b, undefined, { sensitivity: 'base' });
337	}
