560		 *
561		 * Deleting a category leaves its expenses intact but nulls their category
562		 * (`expense_categories.category_id` is `ON DELETE SET NULL`), so those
563		 * expenses drop to Uncategorized. The hierarchy editor uses this count to
564		 * warn the maintainer how many expenses are affected before confirming.
565		 *
566		 * @param categoryId - Category ID to count expenses for
567		 * @returns Number of expenses linked to the category
568		 */
569		async countCategoryExpenses(categoryId: string): Promise<number> {
570			if (!categoryId) {
571				throw new Error('Category ID is required');
572			}
573	
574			// Ask PostgREST for an exact count with `head: true` (no rows returned).
575			// A plain select would be capped at the default 1000-row limit, so a
576			// category with more than 1000 expenses would undercount — the same cap
577			// ExpenseService.getExpenses had to page around.
578			const { count, error } = await this.supabase
579				.from('expense_categories')
580				.select('receipt_id', { count: 'exact', head: true })
581				.eq('category_id', categoryId);
582	
583			if (error) {
584				throw new Error(error.message);
585			}
586	
587			return count ?? 0;
