45	/** Parse a possibly-string/number/other value into a finite number, or null. */
46	function toNum(v: unknown): number | null {
47		if (typeof v === 'number') return Number.isFinite(v) ? v : null;
48		if (typeof v === 'string') {
49			const n = parseFloat(v.replace(/[^0-9.-]/g, ''));
50			return Number.isFinite(n) ? n : null;
51		}
52		return null;
53	}
