55	/**
56	 * Extracts receipt fields from an image/PDF URL using Mistral's vision model.
57	 * Uses the chat completion API with pixtral-12b-2409 (same approach as OcrService.ts).
58	 * PDFs use document_url, images use image_url.
59	 * Note: Requires Deno.env to have MISTRAL_API_KEY.
60	 */
61	export async function ocrFromUrl(
62		fileUrl: string,
63		mimeType: string,
64		deps: MistralDeps = {}
65	): Promise<OcrResult> {
66		const fetchFn = deps.fetchFn ?? fetch;
67		const apiKey = (deps.env ?? getEnv)('MISTRAL_API_KEY');
68		if (!apiKey) throw new Error('MISTRAL_API_KEY not set');
69	
70		// Determine content type based on MIME type (matches OcrService.ts pattern)
71		const isPdf = mimeType.toLowerCase().includes('pdf');
72		const contentType = isPdf ? 'document_url' : 'image_url';
73		const urlKey = isPdf ? 'document_url' : 'image_url';
74	
75		console.log(`OCR processing ${isPdf ? 'PDF' : 'image'}: ${fileUrl.substring(0, 80)}...`);
76	
77		const chatRes = await fetchFn('https://api.mistral.ai/v1/chat/completions', {
78			method: 'POST',
79			headers: {
80				Authorization: `Bearer ${apiKey}`,
81				'Content-Type': 'application/json'
82			},
83			body: JSON.stringify({
84				model: 'pixtral-12b-2409',
85				messages: [
86					{
87						role: 'user',
88						content: [
89							{
90								type: 'text',
91								text: 'Extract fields from the receipt. Respond as JSON with keys: transaction_date (YYYY-MM-DD), raw_date_text (the date exactly as printed on the receipt, verbatim — keep the original separators and digits, do not reinterpret), total_amount (number), tax (number), merchant_name (string), currency (ISO 4217), credit_card_name (string), credit_card_last_4 (string). Default currency to CAD unless the receipt explicitly states a different currency. A bare "$" sign means CAD.'
92							},
93							{
94								type: contentType,
95								[urlKey]: fileUrl
96							}
97						]
98					}
99				],
100				response_format: { type: 'json_object' }
101			})
102		});
103	
104		if (!chatRes.ok) {
105			const errorText = await chatRes.text();
106			throw new Error(`Mistral vision API failed ${chatRes.status}: ${errorText}`);
107		}
108	
109		const data = await chatRes.json();
110		let content: RawOcrContent = {};
111		try {
112			const text = data?.choices?.[0]?.message?.content ?? '{}';
113			content = typeof text === 'string' ? JSON.parse(text) : text;
114		} catch {
115			/* keep content as {} when the model returns non-JSON */
116		}
117	
118		return {
119			transaction_date: content?.transaction_date ?? null,
120			raw_date_text: content?.raw_date_text ?? null,
121			total_amount: toNum(content?.total_amount),
122			tax: toNum(content?.tax),
123			merchant_name: content?.merchant_name ?? null,
124			currency: content?.currency ?? null,
125			credit_card_name: content?.credit_card_name ?? null,
126			credit_card_last_4: content?.credit_card_last_4 ?? null
127		};
128	}
