/**
 * CSVExportService
 *
 * Service for exporting expenses to CSV format
 * Specification: specs/specifications/expense-csv-export.md
 *
 * Traceable to:
 * - #{#exp2a} - CSV File Format Structure (IMPLEMENTED)
 * - #{#exp2b} - CSV Data Transformation (IMPLEMENTED)
 * - #{#exp3a} - CSV File Download Mechanism (IMPLEMENTED)
 * - #{#exp4a} - CSV Export Service Implementation (IMPLEMENTED)
 */

import type { Expense } from './ExpenseService';

/**
 * Date filter types for filename generation
 */
export type DateFilterType = 'all' | 'last_30' | 'last_90' | 'custom';

/**
 * CSVExportService Class
 * Handles CSV generation, formatting, and download
 */
export class CSVExportService {
	/**
	 * Convert array of expenses to CSV format
	 * #{#exp2a} CSV File Format Structure
	 * #{#exp2b} CSV Data Transformation
	 *
	 * @param expenses - Array of expense objects to export
	 * @returns CSV string with headers and data rows
	 */
	exportExpensesToCSV(expenses: Expense[]): string {
		// #{#exp4a} Criterion 2: Validate input
		if (expenses === null || expenses === undefined) {
			throw new Error('Expenses array is required');
		}

		// #{#exp2a} Criterion 2: CSV header row
		const headers = ['Date', 'Merchant Name', 'Amount', 'Category'];
		const csvLines: string[] = [headers.join(',')];

		// #{#exp4a} Criterion 3: Handle empty array - return headers only
		if (expenses.length === 0) {
			return csvLines.join('\n');
		}

		// Process each expense into a CSV row
		for (const expense of expenses) {
			const row = this.formatExpenseRow(expense);
			csvLines.push(row);
		}

		// #{#exp2a} Criterion 9: Use LF line endings
		return csvLines.join('\n');
	}

	/**
	 * Format a single expense as a CSV row
	 * #{#exp2a} #{#exp2b}
	 *
	 * @param expense - Expense object to format
	 * @returns CSV row string
	 */
	private formatExpenseRow(expense: Expense): string {
		// #{#exp2b} Criterion 1: Format date as YYYY-MM-DD
		const date = this.formatDate(expense.transaction_date);

		// #{#exp2b} Criterion 2: Sanitize merchant name (trim whitespace)
		const merchantName = this.escapeCSVField(expense.merchant_name.trim());

		// #{#exp2b} Criterion 3, 4: Format amount (positive, 2 decimals)
		const amount = this.formatAmount(expense.total_amount);

		// #{#exp2b} Criterion 6: Handle missing category
		const category = this.escapeCSVField(expense.category_name?.trim() || '');

		return `${date},${merchantName},${amount},${category}`;
	}

